"""Observe existing ParameterSet copy and serialization behavior."""
import copy
import json
import pickle
import warnings

import pytest


source = pytest.param(7, id="example")
operations = {"copy": copy.copy, "deepcopy": copy.deepcopy, "pickle": lambda value: pickle.loads(pickle.dumps(value))}
rows = {}
for name, operation in operations.items():
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        try:
            value = operation(source)
            rows[name] = {"same_value": value == source, "same_type": type(value) is type(source)}
        except Exception as exc:
            rows[name] = {"error": type(exc).__name__}
    rows[name]["warnings"] = [w.category.__name__ for w in caught]
print(json.dumps(rows, sort_keys=True))
expected = {"same_value": True, "same_type": True, "warnings": []}
raise SystemExit(0 if all(row == expected for row in rows.values()) else 42)

